class Sum implements Op {
    public int apply(int[] xs) {
        int t = 0;
        for (int x : xs) t += x;
        return t;
    }
}

class Product implements Op {
    public int apply(int[] xs) {
        int t = 1;
        for (int x : xs) t *= x;
        return t;
    }
}

class Calc {
    private Op op;

    Calc(Op op) { this.op = op; }

    void setOp(Op op) { this.op = op; }

    int run(int[] xs) { return op.apply(xs); }
}

public class Example {
